            ["Welcome.Step3.Title"] = "优化原理与效果",
            ["Welcome.Step3.Content"] = "优化原理：\n通过调整 CPU 调度策略、内存管理、网络优先级等系统底层参数，降低系统延迟，减少不必要的后台占用，让更多资源分配给游戏进程。\n\n实际体验：\n降低系统延迟后，鼠标移动会更跟手、画面更流畅丝滑、操作响应更灵敏。无论什么配置的电脑，都能感受到操作体验的提升。\n\n效果说明：\n优化效果因硬件配置、系统环境和游戏类型而异，但对大部分用户都有积极作用。",
            ["Welcome.Step4.Title"] = "支持作者",
