            ["RestorePoint.CreateFailedDetail"] = "创建还原点失败，可能原因：\n• 系统还原服务未运行\n• 磁盘空间不足（至少需要300MB）\n• 已达到24小时创建限制\n• 系统保护已禁用\n\n建议：检查系统还原设置或稍后重试。",
