        ["PowerEditor.AggressiveModeWarningMessage"] = "激进模式将让 CPU 保持 100% 最低频率全速运行，以获得极致性能。\n\n⚠️ 请注意以下风险：\n\n• 温度升高：CPU 温度可能上升 10-15°C\n• 功耗增加：整机功耗可能增加 20-30%\n• 噪音提升：风扇转速会明显提高\n• 稳定性：部分系统可能出现不稳定\n\n💡 建议：\n• 确保散热系统良好（塔式散热器或水冷）\n• 监控温度，避免超过 85°C\n• 仅在游戏时使用，日常使用请关闭\n\n确定要启用激进模式吗？",
