        ["AggressiveMode.DetailTitle"] = "🔥 激进模式详细说明",
        ["AggressiveMode.DetailMessage"] = @"【什么是激进模式？】
激进模式会在智能匹配的基础上进一步提升性能，通过调整电源管理参数来减少CPU降频和核心休眠，适合追求极致帧率的用户。

【具体调整的参数】
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
参数名称                标准模式 → 激进模式
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
最低处理器状态          85-95%  → 100%
性能检查间隔            1000ms  → 500ms
核心停放最小值          70-90%  → 100%
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

【特殊处理】
• AMD Ryzen X3D 系列：最低处理器状态保持 90%
  （避免 3D V-Cache 性能下降）
• 其他 CPU：全部参数激进化

【可能的影响】
✅ 性能提升
  • CPU 响应更快，减少降频延迟
  • 游戏帧率可能有小幅提升
  • 适合竞技类游戏

⚠️ 副作用
  • 功耗增加：CPU 持续高频运行
  • 温度上升：散热压力增大
  • 风扇噪音：可能更明显
  • 电池续航：笔记本续航时间缩短

【使用建议】
• 台式机：可以放心使用（前提是散热良好）
• 笔记本：建议插电使用，注意散热
• 如果温度过高或噪音过大，请关闭激进模式
• 不建议长时间开启（日常办公时可关闭）

【透明声明】
本软件仅调整 Windows 电源计划参数，不会修改 BIOS 设置或进行硬件超频。所有调整都是可逆的，关闭激进模式即可恢复。",
        
